/**
 * RepeaterImport — generated by `remotion-ui import-ae` from repeater.json (Bodymovin 5.5.7).
 * 512×512 at 60 fps, 180 frames.
 *
 * Plain data on top of `ae-motion`: keyframe frames are this composition's
 * frames, speed is units per second, scale is a factor and opacity is 0–1.
 * Edit a key, a colour or a layer's inPoint/outPoint/startTime and re-render.
 */
import {
  AeComposition,
  AeLayer,
  shapeLayer,
  group,
  star,
  fill,
  stroke,
  repeater,
} from "@/remotion/lib/ae-import";

/** "Layer" — shape layer, frames 0–180. */
const layerLayer = shapeLayer({
  name: "Layer",
  inPoint: 0,
  outPoint: 180,
  transform: { anchor: [256, 256], position: [256, 256] },
  contents: [
    group(
      "PolyStar",
      [
        star({ position: [80, 120], points: 5, outerRadius: 80, innerRadius: 40 }),
        stroke({ color: "#007fff", width: 1 }),
        fill({ color: "#fffa48" }),
        repeater({
          copies: 4,
          composite: "above",
          transform: {
            anchor: [80, 120],
            position: [130, 0],
            rotation: 137.508,
            endOpacity: 0.5,
          },
        }),
      ],
      { anchor: [65.3373, 117.7791], position: [73.9343, 93.7075] },
    ),
  ],
});

export const Layer = () => <AeLayer layer={layerLayer} />;

/** The composition. Layers are listed bottom of the AE timeline first — later ones draw on top. */
export const RepeaterImport = () => (
  <AeComposition width={512} height={512} fps={60}>
    <Layer />
  </AeComposition>
);

/** Register with `<Composition {...config} />`; `remotion-ui import-ae` adds it to Root.tsx for you. */
export const repeaterImportComposition = {
  id: "RepeaterImport",
  component: RepeaterImport,
  durationInFrames: 180,
  fps: 60,
  width: 512,
  height: 512,
};
